        "path": "src/examples/order-detail/order.types.ts",
        "content": "/** Tipos da tela de detalhe de pedido (showcase OrderDetail). */\n\nexport type OrderStatus = \"paid\" | \"pending\" | \"refunded\";\nexport type FulfillmentStatus = \"fulfilled\" | \"unfulfilled\" | \"partial\";\n\nexport interface OrderItem {\n  id: string;\n  name: string;\n  sku: string;\n  /** Preço unitário em centavos? Não — em reais (number) pra simplicidade do mock. */\n  price: number;\n  qty: number;\n  /** Cor do thumb placeholder (hex). */\n  thumb: string;\n}\n\nexport interface OrderActivity {\n  id: string;\n  /** Cabeçalho do grupo de data (ex: \"Domingo, 06 de março\"). */\n  dateGroup: string;\n  title: string;\n  description?: string;\n  time: string;\n  /** true = evento concluído (verde); false = etapa do fluxo (brand). */\n  done?: boolean;\n}\n\nexport interface OrderComment {\n  id: string;\n  author: string;\n  initials: string;\n  colorHex?: string;\n  when: string;\n  text: string;\n}\n\nexport interface OrderAttachment {\n  id: string;\n  name: string;\n  kind: \"pdf\" | \"image\";\n  size: string;\n}\n\nexport type OrderTagColor =\n  | \"success\"\n  | \"primary\"\n  | \"warning\"\n  | \"neutral\"\n  | \"danger\"\n  | \"info\";\n\nexport interface OrderTag {\n  label: string;\n  color: OrderTagColor;\n}\n\nexport interface OrderCustomer {\n  firstName: string;\n  middleName?: string;\n  lastName: string;\n  initials: string;\n  colorHex?: string;\n  email: string;\n  phone: string;\n  customerId: string;\n  accountType: string;\n  registeredAt: string;\n  active: boolean;\n  previousOrders: number;\n}\n\nexport interface Order {\n  id: string;\n  status: OrderStatus;\n  fulfillment: FulfillmentStatus;\n  placedAt: string;\n  source: string;\n\n  items: OrderItem[];\n  subtotal: number;\n  shipping: number;\n  tax: number;\n  discountCode?: string;\n  discountLabel?: string;\n  discountValue?: number;\n  total: number;\n\n  customer: OrderCustomer;\n\n  shippingAddress: {\n    line1: string;\n    line2?: string;\n    city: string;\n    state: string;\n    zip: string;\n    country: string;\n    carrier: string;\n    tracking: string;\n    eta: string;\n  };\n\n  billing: {\n    address: string;\n    cityState: string;\n    country: string;\n    method: string;\n    transactionId: string;\n    paymentDate: string;\n  };\n\n  note: string;\n  internalNote: string;\n  tags: OrderTag[];\n\n  activity: OrderActivity[];\n  comments: OrderComment[];\n  attachments: OrderAttachment[];\n}\n",
